CREATE OR REPLACE PROCEDURE idq_production_eks_calculation.srmara_eks_item_constructskfromea_ins()
BEGIN
INSERT INTO idq_production_eks_calculation.stmara_eks_item_2 (itemid, bitflag, employeeid, cr_locationid, itemgrouptypeid, itemno, shortdesc_int, shortdesc_nat, description_int, description_nat, in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, zlegacysatnr, zactive, zmtart, zmatkl, zbismt, zmeins, zzeinr, ztragr, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, zinhme, zinhal, zvpreh, zisvalidbitflag, zisin_use, zisfood, ziscurrentcontract, znegotiatingcountry, zarticletype, zitem_ba, zsource, constructed, constructedfrom, zskcasesize, targetsystem, targetclient)
(SELECT CAST(itemid AS INTEGER) AS itemid, bitflag, CAST(employeeid AS INTEGER) AS employeeid, CAST(cr_locationid AS INTEGER) AS cr_locationid, CAST(itemgrouptypeid AS INTEGER) AS itemgrouptypeid, CAST(itemno AS INTEGER) AS itemno, shortdesc_int, shortdesc_nat, description_int, description_nat, CAST(in_use AS INTEGER) AS in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, SUBSTR(CAST(zlegacysatnr AS STRING), 1, 50) AS zlegacysatnr, CAST(zactive AS INTEGER) AS zactive, zmtart, zmatkl, SUBSTR(CAST(zbismt AS STRING), 1, 18) AS zbismt, zmeins, zzeinr, ztragr, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, SUBSTR(CAST(zinhme AS STRING), 1, 3) AS zinhme, zinhal, CAST(zvpreh AS INTEGER) AS zvpreh, CAST(zisvalidbitflag AS INTEGER) AS zisvalidbitflag, CAST(zisin_use AS INTEGER) AS zisin_use, CAST(zisfood AS INTEGER) AS zisfood, CAST(ziscurrentcontract AS INTEGER) AS ziscurrentcontract, znegotiatingcountry, zarticletype, CAST(zitem_ba AS INTEGER) AS zitem_ba, zsource, constructed, SUBSTR(CAST(constructedfrom AS STRING), 1, 255) AS constructedfrom, CAST(zskcasesize AS INTEGER) AS zskcasesize, targetsystem, targetclient
    FROM idq_production_eks_calculation.srmara_eks_item_constructskfromea_inssel_2);
END;
